// Build ONE message from all change rows (and any store that could not be read).
// slackText uses Slack link markup; emailText is plain text for the Send Email alternative.
const MAX_LINES = 40;
const rows = $input.all().map((i) => i.json);
const changes = rows.filter((r) => r.recordType === 'variant' || r.recordType === 'product');
const problems = rows.filter((r) => r.recordType === 'store_status');

const ORDER = { price_changed: 0, back_in_stock: 1, out_of_stock: 2, removed: 3, new: 4 };
changes.sort((a, b) => (ORDER[a.changeType] ?? 9) - (ORDER[b.changeType] ?? 9));

const counts = {};
for (const r of changes) counts[r.changeType] = (counts[r.changeType] ?? 0) + 1;

function name(r) {
  const product = r.productTitle ?? r.title ?? 'Unknown product';
  const variant = r.variantTitle && r.variantTitle !== 'Default Title' ? ` / ${r.variantTitle}` : '';
  return `${product}${variant}${r.sku ? ` (SKU ${r.sku})` : ''}`;
}

function what(r) {
  const cur = r.currency ? ` ${r.currency}` : '';
  const price = r.price ?? r.priceMin;
  const prev = r.previousPrice ?? r.previousPriceMin;
  switch (r.changeType) {
    case 'price_changed': return `price ${prev} -> ${price}${cur}`;
    case 'back_in_stock': return `back in stock at ${price}${cur}`;
    case 'out_of_stock': return 'out of stock';
    case 'removed': return `removed (last price ${prev}${cur})`;
    case 'new': return `new at ${price}${cur}`;
    default: return r.changeType;
  }
}

const shown = changes.slice(0, MAX_LINES);
const more = changes.length - shown.length;
const summary = Object.entries(counts).map(([k, v]) => `${v} ${k.replace(/_/g, ' ')}`).join(', ');
const stores = [...new Set(changes.map((r) => r.storeDomain).filter(Boolean))].join(', ');
const title = changes.length
  ? `Shopify changes${stores ? ' on ' + stores : ''}: ${summary}`
  : 'Shopify tracker: no changes, but some stores could not be read';

// Slack treats &, < and > as markup, so escape them in product names.
const esc = (s) => String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');

const slack = [`*${esc(title)}*`];
const email = [title, ''];
for (const r of shown) {
  slack.push(`• <${r.url}|${esc(name(r))}>: ${esc(what(r))}`);
  email.push(`- ${name(r)}: ${what(r)}\n  ${r.url}`);
}
if (more > 0) {
  slack.push(`...and ${more} more (see the run's dataset in Apify Console)`);
  email.push(`...and ${more} more (see the run's dataset in Apify Console)`);
}
for (const p of problems) {
  const line = `Store ${p.storeDomain ?? p.input}: ${p.status} - ${p.message}`;
  slack.push(`:warning: ${esc(line)}`);
  email.push(`WARNING ${line}`);
}

return [{
  json: {
    changeCount: changes.length,
    problemCount: problems.length,
    subject: title,
    slackText: slack.join('\n'),
    emailText: email.join('\n'),
  },
}];
